 IF (#tempRefSyncAxis <> NULL) THEN
    //Axis type TOSynch. Axis
    #statActualTorque := #tempRefSyncAxis^.StatusTorqueData.ActualTorque;

ELSIF (#tempRefPosAxis <> NULL) THEN
    //Axis type is TO_PositioningAxis 
    #statActualTorque := #tempRefPosAxis^.StatusTorqueData.ActualTorque;

ELSIF (#tempRefSpeedAxis <> NULL) THEN
    //Axis type TO_Speed. Axis
    #statActualTorque := #tempRefSpeedAxis^.StatusTorqueData.ActualTorque;
END_IF;
